<?php
namespace App\Http\Controllers;
use App\Models\{Product,Sale,Customer,User};use Illuminate\Http\Request;use Illuminate\Support\Facades\{Auth,DB,Hash};
class PosController extends Controller{
function dashboard(){return view('dashboard',['sales'=>Sale::whereDate('created_at',today())->count(),'revenue'=>Sale::whereDate('created_at',today())->sum('total'),'products'=>Product::count(),'customers'=>Customer::count(),'low'=>Product::where('stock','<=',5)->orderBy('stock')->take(5)->get(),'recent'=>Sale::latest()->take(8)->get()]);}
function login(){return view('login');}function authenticate(Request $r){$d=$r->validate(['email'=>'required|email','password'=>'required']);if(!Auth::attempt($d,$r->boolean('remember')))return back()->withErrors(['email'=>'อีเมลหรือรหัสผ่านไม่ถูกต้อง']);$r->session()->regenerate();return redirect()->intended('/');}function logout(Request $r){Auth::logout();$r->session()->invalidate();$r->session()->regenerateToken();return redirect('/login');}
function products(){return view('products',['products'=>Product::when(request('q'),fn($q,$s)=>$q->where('name','like','%'.$s.'%'))->orderBy('name')->paginate(15)]);}function saveProduct(Request $r){$d=$r->validate(['name'=>'required|max:100','category'=>'required|in:drink,food,other','price'=>'required|numeric|min:0','stock'=>'required|integer|min:0']);Product::create($d+['active'=>true]);return back()->with('ok','เพิ่มสินค้าแล้ว');}
function customers(){return view('customers',['customers'=>Customer::latest()->paginate(15)]);}function saveCustomer(Request $r){Customer::create($r->validate(['name'=>'required|max:100','phone'=>'nullable|max:30']));return back()->with('ok','เพิ่มสมาชิกแล้ว');}
function employees(){abort_unless(Auth::user()->role==='admin',403);return view('employees',['employees'=>User::latest()->paginate(15)]);}function saveEmployee(Request $r){abort_unless(Auth::user()->role==='admin',403);$d=$r->validate(['name'=>'required','email'=>'required|email|unique:users','password'=>'required|min:8','role'=>'required|in:admin,cashier']);$d['password']=Hash::make($d['password']);User::create($d);return back()->with('ok','เพิ่มพนักงานแล้ว');}
function sales(){return view('sales',['sales'=>Sale::with('items','cashier')->latest()->paginate(20)]);}function pos(){return view('pos',['products'=>Product::where('active',1)->where('stock','>',0)->orderBy('category')->get(),'customers'=>Customer::orderBy('name')->get()]);}
function checkout(Request $r){$d=$r->validate(['items'=>'required|array|min:1','items.*.id'=>'required|exists:products,id','items.*.qty'=>'required|integer|min:1','customer_id'=>'nullable|exists:customers,id','payment_method'=>'required|in:cash,transfer,card','paid_amount'=>'required|numeric|min:0']);$s=DB::transaction(function()use($d,$r){$rows=[];$sub=0;foreach($d['items'] as $i){$p=Product::whereKey($i['id'])->lockForUpdate()->firstOrFail();if($p->stock<$i['qty'])throw \Illuminate\Validation\ValidationException::withMessages(['items'=>'สินค้า '.$p->name.' มีไม่พอ']);$sub+=$p->price*$i['qty'];$rows[]=[$p,$i['qty']];}$c=isset($d['customer_id'])?Customer::find($d['customer_id']):null;$s=Sale::create(['receipt_no'=>'POS-'.now()->format('YmdHis').'-'.random_int(10,99),'user_id'=>$r->user()->id,'customer_id'=>$c?->id,'customer_name'=>$c?->name??'ลูกค้าทั่วไป','subtotal'=>$sub,'discount'=>0,'total'=>$sub,'payment_method'=>$d['payment_method'],'paid_amount'=>$d['paid_amount'],'change_amount'=>max(0,$d['paid_amount']-$sub)]);if($d['paid_amount']<$sub)throw \Illuminate\Validation\ValidationException::withMessages(['paid_amount'=>'ยอดรับชำระไม่พอ']);foreach($rows as [$p,$q]){$s->items()->create(['product_id'=>$p->id,'product_name'=>$p->name,'price'=>$p->price,'qty'=>$q,'subtotal'=>$p->price*$q]);$p->decrement('stock',$q);}if($c)$c->increment('points',(int)($sub/100));return $s;});return redirect('/sales/'.$s->id)->with('ok','ขายสำเร็จ');}
function receipt(Sale $sale){$sale->load('items','cashier');return view('receipt',compact('sale'));}function report(){ $from=request('from',now()->startOfMonth()->toDateString());$to=request('to',today()->toDateString());$q=Sale::whereDate('created_at','>=',$from)->whereDate('created_at','<=',$to);return view('report',['sales'=>(clone $q)->with('cashier')->latest()->paginate(20),'from'=>$from,'to'=>$to,'total'=>(clone $q)->sum('total'),'count'=>(clone $q)->count()]);}
}
